124	     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
125	     * absent, so owners without a customerCode map cleanly.
126	     */
127	    default Integer checkDigit(Owner owner) {
128	        String customerCode = owner.getCustomerCode();
129	        if (customerCode == null) {
130	            return null;
131	        }
132	        int sum = 0;
133	        boolean dbl = true;
134	        for (int i = customerCode.length() - 1; i >= 0; i--) {
135	            char c = customerCode.charAt(i);
136	            if (c < '0' || c > '9') {
137	                continue;
138	            }
139	            int d = c - '0';
140	            if (dbl) {
141	                d *= 2;
142	                if (d > 9) {
143	                    d -= 9;
144	                }
145	            }
146	            sum += d;
147	            dbl = !dbl;
148	        }
149	        return (10 - (sum % 10)) % 10;
