package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import tools.jackson.databind.node.ObjectNode;

/** possible-duplicate: a new owner that is not a hard duplicate but shares an existing owner's
 * lastName and postcode with a DIFFERENT telephone is still created, and returns possibleDuplicate
 * true with possibleDuplicateOf set to the matching owner's id; otherwise possibleDuplicate false. */
@Tag("cp36")
class Cp36Tests extends AcceptanceBase {

	@Test
	void coreFlagsPossibleDuplicate() throws Exception {
		ObjectNode a = ownerNode();
		a.put("postcode", "2000");
		int idA = createOwnerOk(a);

		ObjectNode b = ownerNode(); // unique telephone/first name/city/address
		b.set("lastName", a.get("lastName")); // same lastName
		b.put("postcode", "2000"); // same postcode, different telephone
		int idB = createOwnerOk(b);

		getOwner(idB)
				.andExpect(jsonPath("$.possibleDuplicate").value(true))
				.andExpect(jsonPath("$.possibleDuplicateOf").value(idA));
	}

	@Test
	void functionalityUniqueOwnerNotFlagged() throws Exception {
		int id = createOwnerOk(withPostcode(ownerNode()));
		getOwner(id).andExpect(jsonPath("$.possibleDuplicate").value(false));
	}

	@Test
	void functionalitySameLastNameDifferentPostcodeNotFlagged() throws Exception {
		ObjectNode a = ownerNode();
		a.put("postcode", "2000");
		createOwnerOk(a);

		ObjectNode b = ownerNode();
		b.set("lastName", a.get("lastName")); // same lastName
		b.put("postcode", "2001"); // different postcode
		int idB = createOwnerOk(b);

		getOwner(idB).andExpect(jsonPath("$.possibleDuplicate").value(false));
	}
}

